  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "In nonhuman primates, raltitrexed showed limited CSF penetration (0.6–2%) and was detected in CSF only after a 10 mg/m2 dose, indicating poor CNS access for a structurally related antifolate.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Ex vivo biodistribution in mice showed extremely low brain radioactivity after 211At-AITM injection despite high mGluR1 expression in brain, indicating failure to cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "In dogs, radioactively labeled 5-MTHF achieved rapid CSF equilibration within 3 h after IV bolus, demonstrating that some folate-related compounds can access the CNS.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The most similar direct in-vivo evidence is mixed, but the closest antifolate and multiple other small-molecule/organic-anion analogs show poor BBB/CSF penetration; therefore meaningful CNS access is not supported.",
  "evidence_gaps": [
    "No direct query-specific CNS exposure data; evidence is indirect via analogs with moderate-to-low similarity.",
    "Positive folate transport evidence may not transfer if the query is an antifolate or organic anion rather than a natural folate substrate.",
    "Mixed directions among top similar molecules limit confidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

